#include <bits/stdc++.h>
using namespace std;

vector<int> solve(vector<int> nums, int target) {
    // Write your solution here
    return {};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<string> lines;
    string line;
    while (getline(cin, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    size_t pos = 0;
    int numsLen = stoi(lines[pos++]);
    vector<int> nums(numsLen);
    if (numsLen > 0) {
        istringstream iss(lines[pos]);
        for (auto &v : nums) iss >> v;
    }
    pos++;
    int target = stoi(lines[pos++]);
    vector<int> result = solve(nums, target);
    for (size_t i = 0; i < result.size(); i++) {
        if (i) cout << " ";
        cout << result[i];
    }
    cout << "\n";
    return 0;
}

