        int[][] intervals = new int[intervalsLen][2];
        for (int i = 0; i < intervalsLen; i++) {
            StringTokenizer st = new StringTokenizer(lines.get(pos++));
            intervals[i][0] = Integer.parseInt(st.nextToken());
            intervals[i][1] = Integer.parseInt(st.nextToken());
        }
        int[][] result = solve(intervals);
        for (int[] row : result) {
            System.out.println(row[0] + " " + row[1]);
        }
    }
}

